<template>
 <view class="favorites-page"><view class="favorites-hero"><view><text class="eyebrow">灵感收集 · 慢慢回看</text><text class="title">我的收藏</text><text class="subtitle">把触动你的创作，留给下一次相遇。</text></view><image src="/static/xiaozhi-caring.png" mode="aspectFit"/></view>
 <view class="toolbar"><text>{{total}} 份可查看的创作</text><button :disabled="loading" @click="load(1)">刷新收藏</button></view><text class="hint">仅你可见的收藏清单。已下架或不可访问的作品不会展示。</text>
 <view v-if="error" class="failure"><text>{{error}}</text><button :disabled="loading" @click="load(failedPage)">重试</button></view>
 <view v-if="loading&&!records.length" class="grid"><view v-for="i in 3" :key="i" class="zy-skeleton skeleton"/></view>
 <view v-else-if="!records.length&&!error" class="empty"><image src="/static/xiaozhi-happy.png" mode="aspectFit"/><text>还没有收藏的创作</text><text class="hint">遇到喜欢的作品，点一下收藏就能在这里找到。</text><button class="primary" @click="community">去社区发现</button></view>
 <view class="grid"><view v-for="item in records" :key="item.id" class="saved-card"><button class="card-open" @click="open(item)"><image v-if="item.coverUrl&&!failedImages[item.id]" class="cover" :src="fullUrl(item.coverUrl)" mode="aspectFill" @error="failedImages[item.id]=true"/><view v-else class="cover cover-empty"><image src="/static/xiaozhi-avatar.png" mode="aspectFit"/><text>{{item.mediaType==='video'?'创作影像':'一份创作的心意'}}</text></view><view class="card-copy"><text class="tag">{{Number(item.visible)===1?'社区作品':'仅本人可见'}} · {{item.mediaType==='video'?'视频':item.mediaType==='text'?'文字':'手作'}}</text><text class="card-title">{{item.title}}</text><text class="excerpt">{{item.message||'点开看看这份创作的故事。'}}</text></view></button><view class="card-footer"><text>收藏于 {{String(item.savedAt||'').slice(0,10)}}</text><button :disabled="!!removing" @click="remove(item)">{{removing===item.id?'处理中…':'取消收藏'}}</button></view></view></view>
 <button v-if="records.length<total&&!error" class="load-more" :disabled="loading" :loading="loading" @click="load(page+1)">查看更多收藏</button><text class="footnote">本系统不能替代专业心理咨询</text>
 </view>
</template>
<script setup>
import {ref} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import {http} from '../../utils/request'
import {API_BASE_URL} from '../../utils/config'
import {workPath} from '../../utils/work-navigation'
const records=ref([]),total=ref(0),page=ref(0),loading=ref(false),error=ref(''),failedPage=ref(1),removing=ref(''),failedImages=ref({})
onShow(()=>load(1))
async function load(target){if(loading.value)return;loading.value=true;error.value='';failedPage.value=target;try{const data=await http.get('/api/works/favorites',{data:{page:target}});records.value=target===1?data.records:records.value.concat(data.records);total.value=Number(data.total);page.value=target}catch(e){error.value=e.message||'收藏加载失败'}finally{loading.value=false}}
function remove(item){uni.showModal({title:'取消收藏',content:'这会从你的收藏清单移除作品，不会删除作品本身。',success:async r=>{if(!r.confirm||removing.value)return;removing.value=item.id;try{await http.del('/api/works/favorites/'+item.id);await load(1)}catch(e){uni.showToast({title:e.message||'取消失败，请重试',icon:'none'})}finally{removing.value=''}}})}
function open(item){uni.navigateTo({url:workPath(item.id)})}
function community(){uni.switchTab({url:'/pages/work/list'})}
function fullUrl(url){return /^https?:\/\//.test(url)||url.startsWith('/static/')?url:API_BASE_URL+url}
</script>
<style scoped>
.favorites-page{max-width:1180px;margin:auto;padding:28rpx 28rpx 80rpx;color:#233d34;box-sizing:border-box}.favorites-hero{background:linear-gradient(120deg,#e8efe4,#f6f2e8);border:1rpx solid #dfe7dc;border-radius:28rpx;padding:36rpx;display:flex;align-items:center;justify-content:space-between;gap:20rpx}.favorites-hero image{width:150rpx;height:170rpx;flex-shrink:0}.eyebrow,.title,.subtitle{display:block}.eyebrow{font-size:22rpx;color:#2f7566}.title{font-family:var(--zy-serif);font-size:44rpx;margin:12rpx 0}.subtitle,.hint{font-size:24rpx;color:#718478;line-height:1.7}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:20rpx;margin-top:24rpx;font-size:26rpx}.toolbar button,.card-footer button{font-size:23rpx;color:#2f7566;background:transparent;padding:12rpx 0;margin:0}button::after{border:0}.hint{display:block;margin:12rpx 0 24rpx}.grid{display:grid;grid-template-columns:minmax(0,1fr);gap:24rpx}.saved-card{background:#fff;border:1rpx solid #dfe7dc;border-radius:24rpx;overflow:hidden}.card-open{display:block;text-align:left;background:#fff;padding:0;margin:0;border-radius:0;line-height:1.6;width:100%}.cover{width:100%;height:320rpx;display:block}.cover-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16rpx;background:#e8efe4;color:#718478;font-size:24rpx}.cover-empty image{width:100rpx;height:100rpx}.card-copy{padding:24rpx}.tag{font-size:21rpx;color:#2f7566}.card-title{display:block;font-size:32rpx;margin:12rpx 0;overflow-wrap:anywhere}.excerpt{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:#718478;font-size:25rpx;overflow-wrap:anywhere}.card-footer{display:flex;align-items:center;justify-content:space-between;padding:12rpx 24rpx;border-top:1rpx solid #eef1eb;font-size:21rpx;color:#718478}.empty{display:flex;align-items:center;flex-direction:column;padding:64rpx 20rpx;text-align:center;font-size:30rpx}.empty image{width:200rpx;height:200rpx}.primary,.load-more{background:#2f7566;color:#fff;font-size:26rpx;padding:16rpx 28rpx;border-radius:16rpx}.load-more{margin:28rpx auto}.skeleton{height:420rpx}.failure{background:#fff2eb;color:#964d30;border-radius:16rpx;padding:20rpx;margin:20rpx 0;font-size:26rpx}.footnote{display:block;text-align:center;color:#718478;font-size:22rpx;margin-top:40rpx}@media(min-width:680px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(min-width:1050px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
